A.record=record;A.mark=mark;A.checkpoint=(label='직접 저장 이력')=>{let n=note();if(n){record(n,label);mark(n);baseline();persist()}};
persist=function(){track();MEMOAStore.queue(db);A.status('저장 중…')};
A.status=function(message){$('saveState').textContent='● '+message;let q=document.getElementById('quick-save-state');if(q)q.textContent=message};
function refresh(){renderSide();renderList();renderEditor();document.dispatchEvent(new CustomEvent('memoa:data-refresh'))}A.refresh=refresh;
A.ready=(async()=>{let primary=await MEMOAStore.load();if(primary&&(!db._savedAt||primary._savedAt>db._savedAt)){try{db=C.normalize(primary)}catch{}}db=C.normalize(db);db.versionGroups ||= {};for(const n of db.notes){if(!Object.keys(n._vc||{}).length)n._vc={[actor]:++sequence};if(!n.history?.length&&n.html.trim())record(n,'이력 기록 시작')}baseline();hydrated=true;MEMOAStore.activate(db);refresh();let points=await MEMOAStore.snapshots();if(!points.some(p=>new Date(p.at).toDateString()===new Date().toDateString()))MEMOAStore.snapshot(db,'오늘의 자동 복구 지점').catch(()=>{});return true})();
let channel;try{channel=new BroadcastChannel('memoa-records')}catch{}
document.addEventListener('memoa:saved',e=>{if(e.detail.merged){db=C.mergeData(db,e.detail.merged).data;baseline();refresh()}A.status(navigator.onLine?'기기에 저장됨':'오프라인 · 기기에 저장됨');channel?.postMessage({at:e.detail.at,sender:tabId})});document.addEventListener('memoa:save-error',e=>{A.status('저장 실패 · 백업 필요');toast(e.detail.message)});
